local ScrollCaseMaker = {}
local PRODUCTS = {
    simple_leather_scroll_case = { name = "Preprost usnjen tulce za zvitke", leatherCost = 2, woodCost = 1, time = 3, cost = 40, education = 8, happiness = 1, description = "Preprost usnjen tulce za shranjevanje zvitkov." },
    brass_capped_scroll_case = { name = "Medeninastopokrovni tulce", leatherCost = 2, brassCost = 1, woodCost = 1, time = 5, cost = 120, education = 15, happiness = 1, prestige = 2, description = "Medeninastopokrovni tulce za trgovce." },
    silver_trimmed_case = { name = "Srebrnoobrobljeni tulce", leatherCost = 2, silverCost = 1, brassCost = 1, woodCost = 1, time = 8, cost = 300, education = 22, happiness = 2, prestige = 6, description = "Srebrnoobrobljeni tulce za plemiče." },
    gold_inlaid_case = { name = "Zlatovloženi tulce", leatherCost = 2, goldCost = 1, silverCost = 1, brassCost = 1, woodCost = 1, time = 12, cost = 720, education = 32, happiness = 3, prestige = 14, description = "Zlatovloženi tulce za visoke plemiče." },
    jewel_set_case = { name = "Draguljasta tulce", leatherCost = 2, goldCost = 1, silverCost = 1, brassCost = 1, woodCost = 1, jewelCost = 1, time = 16, cost = 1600, education = 42, happiness = 5, prestige = 27, description = "Tulce z draguljem za visoko plemstvo." },
    royal_grand_scroll_case = { name = "Kraljevski veliki tulce", leatherCost = 3, goldCost = 2, silverCost = 2, brassCost = 1, woodCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 3600, education = 60, happiness = 12, prestige = 58, description = "Veliki kraljevski tulce z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    case_workshop = { name = "Tulce delavnica", cost = { gold = 220, wood = 100, stone = 100, leather = 6 }, upkeep = 5, qualityBonus = 5 },
    archival_loft = { name = "Arhivska podstrešje", cost = { gold = 880, wood = 240, stone = 220, silver = 6, brass = 6 }, upkeep = 20, qualityBonus = 18 },
    master_case_atelier = { name = "Mojstrski tulce atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_archival_palace = { name = "Kraljevska arhivska palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
ScrollCaseMaker.leatherStock = 14; ScrollCaseMaker.woodStock = 10; ScrollCaseMaker.brassStock = 10; ScrollCaseMaker.silverStock = 6; ScrollCaseMaker.goldStock = 6; ScrollCaseMaker.jewelStock = 4; ScrollCaseMaker.pearlStock = 4
ScrollCaseMaker.productStock = {}; ScrollCaseMaker.buildings = {}; ScrollCaseMaker.maker = nil; ScrollCaseMaker.activeMaking = {}; ScrollCaseMaker.totalProducts = 0; ScrollCaseMaker.dayTimer = 0
function ScrollCaseMaker.init() ScrollCaseMaker.leatherStock=14; ScrollCaseMaker.woodStock=10; ScrollCaseMaker.brassStock=10; ScrollCaseMaker.silverStock=6; ScrollCaseMaker.goldStock=6; ScrollCaseMaker.jewelStock=4; ScrollCaseMaker.pearlStock=4; ScrollCaseMaker.productStock={}; ScrollCaseMaker.buildings={}; ScrollCaseMaker.maker=nil; ScrollCaseMaker.activeMaking={}; ScrollCaseMaker.totalProducts=0; ScrollCaseMaker.dayTimer=0; print("[ScrollCaseMaker] Royal Scroll Case Maker System initialized (6 products, 4 buildings)") end
function ScrollCaseMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ScrollCaseMaker.maker={name=n or ("Tulcear "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tulcear najet: %s (spretnost: %d)",ScrollCaseMaker.maker.name,s),"success") end; return true end
function ScrollCaseMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ScrollCaseMaker.build(id) local ok,e=ScrollCaseMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ScrollCaseMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ScrollCaseMaker.getQualityBonus() local b=0; for _,bd in ipairs(ScrollCaseMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ScrollCaseMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.leatherCost and ScrollCaseMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.woodCost and ScrollCaseMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.brassCost and ScrollCaseMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and ScrollCaseMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ScrollCaseMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ScrollCaseMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ScrollCaseMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ScrollCaseMaker.buildings==0 then return false,"Potrebna tulce delavnica" end; if not ScrollCaseMaker.maker then return false,"Potreben tulcear" end; return true end
function ScrollCaseMaker.make(pt,qty) qty=qty or 1; local ok,e=ScrollCaseMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.leatherCost then ScrollCaseMaker.leatherStock=ScrollCaseMaker.leatherStock-d.leatherCost*qty end; if d.woodCost then ScrollCaseMaker.woodStock=ScrollCaseMaker.woodStock-d.woodCost*qty end; if d.brassCost then ScrollCaseMaker.brassStock=ScrollCaseMaker.brassStock-d.brassCost*qty end; if d.silverCost then ScrollCaseMaker.silverStock=ScrollCaseMaker.silverStock-d.silverCost*qty end; if d.goldCost then ScrollCaseMaker.goldStock=ScrollCaseMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ScrollCaseMaker.jewelStock=ScrollCaseMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ScrollCaseMaker.pearlStock=ScrollCaseMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ScrollCaseMaker.maker then t=math.max(1,t-math.floor(ScrollCaseMaker.maker.skill/13)) end; table.insert(ScrollCaseMaker.activeMaking,{id="scrollcase_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,education=d.education or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ScrollCaseMaker.completeMaking(m) local q=1.0+(ScrollCaseMaker.getQualityBonus()/100); if ScrollCaseMaker.maker then q=q+(ScrollCaseMaker.maker.skill/140) end; q=math.min(2.5,q); ScrollCaseMaker.productStock[m.productType]=(ScrollCaseMaker.productStock[m.productType] or 0)+m.quantity; ScrollCaseMaker.totalProducts=ScrollCaseMaker.totalProducts+m.quantity; if m.education>0 and _G.state then _G.state.education=(_G.state.education or 0)+m.education end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ScrollCaseMaker.maker then ScrollCaseMaker.maker.itemsMade=ScrollCaseMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ScrollCaseMaker.maker.skill=math.min(100,ScrollCaseMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tulce izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"scrollcase.completed",{productName=m.productName,education=m.education,prestige=m.prestige,happiness=m.happiness}) end end
function ScrollCaseMaker.update(dt) if not _G.state then return end; ScrollCaseMaker.dayTimer=ScrollCaseMaker.dayTimer+dt; if ScrollCaseMaker.dayTimer>=30 then ScrollCaseMaker.dayTimer=0; for i=#ScrollCaseMaker.activeMaking,1,-1 do local m=ScrollCaseMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ScrollCaseMaker.completeMaking(m); table.remove(ScrollCaseMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ScrollCaseMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ScrollCaseMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ScrollCaseMaker.getStats() return {leatherStock=ScrollCaseMaker.leatherStock,woodStock=ScrollCaseMaker.woodStock,brassStock=ScrollCaseMaker.brassStock,silverStock=ScrollCaseMaker.silverStock,goldStock=ScrollCaseMaker.goldStock,jewelStock=ScrollCaseMaker.jewelStock,pearlStock=ScrollCaseMaker.pearlStock,productStock=ScrollCaseMaker.productStock,numBuildings=#ScrollCaseMaker.buildings,hasMaker=ScrollCaseMaker.maker~=nil,makerName=ScrollCaseMaker.maker and ScrollCaseMaker.maker.name or "—",makerSkill=ScrollCaseMaker.maker and ScrollCaseMaker.maker.skill or 0,activeMaking=#ScrollCaseMaker.activeMaking,totalProducts=ScrollCaseMaker.totalProducts} end
return ScrollCaseMaker
